//! constitution.rs — twin of skills/engine/canonical-actions/constitution.mjs: DATA statics pressed by the crossing + the
//! hand-ported accessor. NAMES ARE CONTRACT: statics and fns carry exact JS names.
// QUALITY: 80/100 — pressed statics + trivial hand accessor; blob unreadable by design, surface fully tested
use serde_json::Value;
use std::sync::LazyLock;

pub static ACTIONS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#"[{"name":"system.constitution.law","description":"CONSTITUTION management (advisory edits only): list the composed constitution (community+language+code laws, exceptions), seed the starter library, ratify/dismiss a mined candidate, suspend/unsuspend, reweight (bumps version), or add/remove an exceptions-court entry. input: {op: list|seed|ratify|dismiss|suspend|unsuspend|reweight|except|unexcept, ...}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-law\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.business.gen","description":"CONSTITUTION business-law generation (spends AI): reads the codebase context (entry points · domain vocabulary · recorded decisions) and PROPOSES domain-invariant / security / workflow laws as CANDIDATES to ratify — with a regex detector where checkable, else advise-only. The AI call persists an envelope (the AI-call window). input: {max?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-business-gen\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.law.build","description":"CONSTITUTION custom-law builder (spends AI): turns a plain-English rule description into ONE deterministic law with a scannable detector (regex/absent/path/import/metric/ast) for the wizard to review — does NOT persist (the operator creates it via op:add). Opens the AI-call window. input: {description}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-law-build\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.mine","description":"CONSTITUTION mining ($0, deterministic): pattern census over this repo (naming case, shared error-helper adherence, …) → proposes code-rule CANDIDATES with their evidence (count + exemplars) for one-click ratification. Never auto-enacts. input: {folder?, max_files?, threshold?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-mine\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.estimate","description":"CONSTITUTION rebuild estimate (the wizard, pure reads): for a scope, how many files are in it, how many replay from cache (unchanged content + same constitution), how many compute fresh, and a projected time — shown before the click. input: {folder?|files?|base?, max_files?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-estimate\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.judge","description":"CONSTITUTION rebuild ($0, ZERO AI): judges a scope against the composed constitution — every file scored 100-Σ(weight×hits) decomposable to the laws it breaks, every binding scored by target weakness×blast-radius, incremental by content_hash (unchanged files replay). Writes a snapshot with an honest coverage manifest. input: {folder?|files?|base?, max_files?, source?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-judge\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.neighborhood","description":"CONSTITUTION neighborhood canvas ($0, pure reads): for one file, the import graph BOTH directions to N layers (upstream = the blast radius, downstream = what it leans on), every node with its latest-snapshot verdict, every edge with the symbols that cross it (the data story), plus hidden co-change couplings. Feeds the 🕸 neighborhood tab. input: {path, depth?, max_per_ring?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-neighborhood\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.agents","description":"CONSTITUTION agents registry ($0, deterministic, no AI): derives every review SPECIALIST applicable to THIS workspace from the census — languages from the snapshot, frameworks from stack-facts, active packs, ratified laws by concern, the engineering axes. A lens = applicability + laws + slices + persona; rows, never code. input: {}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-agents\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.agent.run","description":"CONSTITUTION specialist run (spends AI, click-is-consent): executes ONE registry specialist against ONE scope (file or folder) — the lens laws + deterministic verdict + source in a single money-guarded call; findings are advisory, parse-or-drop; no court, no synthesis. Opens the AI-call window via the envelope row. input: {agent_id, path, swarm_id?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-agent-run\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.research.suggest","description":"CONSTITUTION web-research suggester (spends AI, ONE low-tier call, click-is-consent): given a case, a small AI call proposes SEARCH ANGLES from its concerns (broken laws, weak axes, language); the deterministic keyless scrape then returns REAL, editable URLs for the research wizard. Opens the AI-call window. input: {path}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-research-suggest\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.paper","description":"CONSTITUTION paper history ($0, the study shelf): save (UPSERT by slug/swarm_id — all sections + widget data in paper_json, the ingredients, and a markdown rendition), list, or get a saved study — retrievable from notebooks, chat grounding, vibe panes. input: {op: save|list|get, ...}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-paper\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.class","description":"CONSTITUTION video class / presentation deck (spends AI, ONE mid call, click-is-consent): PROJECTS a SAVED paper into a slide deck — one axis per slide, a whitelisted drawn widget as the visual, spoken-style speech (narrated by TTS in the video class, shown as text in the presentation). PAPER-ONLY: pass paper_slug or paper_id; raw markdown/reviews/corpora are refused. input: {paper_slug?|paper_id?, label?, swarm_id?, notebook_id? (filing target)}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-class\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.soliloquy","description":"CONSTITUTION soliloquy (spends AI, ONE mid call + TTS, click-is-consent): ONE narrator turns a SAVED paper into a short engineering lecture reorganized for LISTENING — chapters of spoken prose, voiced by the local Kokoro voice (BYOK, key pre-flighted) into one persisted mp3 with chapter timestamps + a transcript. PAPER-ONLY: pass paper_slug or paper_id; raw markdown/corpora are refused. input: {paper_slug?|paper_id?, label?, voice_id?, swarm_id?, notebook_id? (filing target)}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-soliloquy\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.editor","description":"CONSTITUTION study editor (spends AI, ONE high-tier call, click-is-consent): takes the crew's VALIDATED reviews + the deterministic record and writes the paper's connective narrative — introduction, per-file paragraph, discussion, conclusion — didactic, attribution-only (edits, never discovers new findings). Joins the mission swarm via swarm_id. input: {reviews, label?, swarm_id?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-editor\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.check","description":"CONSTITUTION measured check ($0, pure computation, NO writes): re-runs the active content-scope laws (regex/absent/import/ast/stmt) over a CANDIDATE content for one file and compares to the latest snapshot — the short/full PR merge gate shows MEASURED before→after violations, what a fix fixes, and anything it INTRODUCES. input: {path, content}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-check\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.packs","description":"CONSTITUTION engineering packs ($0): named law collections (security · architecture · testing · patterns · react · node · python) that auto-activate from the workspace stack. op:list (status per pack — active · available · compatible · auto), op:enable (install+ratify a pack in one click), op:disable (suspend it). input: {op, id?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-packs\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.pack.gen","description":"CONSTITUTION tech-pack generation (spends AI): the AI authors a batch of deterministic laws for a named technology (a language/framework/library) — optionally grounded in pasted docs — as CANDIDATES to ratify. Broken detectors dropped; opens the AI-call window. input: {tech, docs?, max?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-pack-gen\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.patterns","description":"CONSTITUTION per-file design-pattern readout ($0, informational): reuses code-patterns detectFilePatterns over the file decorators + entry-points → the patterns it uses (Custom Hook · Reducer · Repository · Factory · Observer · Singleton · Middleware · Barrel…) with confidence + evidence. input: {path}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-patterns\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.file","description":"CONSTITUTION per-file snapshot ($0, pure reads): everything the latest snapshot knows about ONE file — engineering health + law compliance, every axis with its parts, the raw signals (loc/complexity/fan-in/transitive/coverage/churn/authors), the law violations, the neighborhood percentiles, and a rendered doc_md ready to sit atop the file. input: {path, snapshot_id?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-file\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.report","description":"CONSTITUTION lens payload (pure reads): a snapshot's health, violations-by-law, worst-risk blocks+bindings (the AI spot list), the composed constitution + candidates + exceptions, deltas vs the prior snapshot, and any AI insights. input: {snapshot_id?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-report\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.insights","description":"CONSTITUTION AI phase (spends budget, risk-gated): ONE low-tier agent per worst-risk spot, fed the broken laws+weights+source, synthesizing insight+fix (never hunting new problems); a 2nd lens only on extreme risk or parse failure. Grounded claims, parse-or-drop, advisory. input: {snapshot_id?, max_spots?, escalate_top?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-insights\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.provenance","description":"CONSTITUTION provenance (root cause as data, $0, zero AI): for one file — the commits that shaped it → the card slugs those commits name → those cards + contracts → the recorded decisions. Unresolved links reported missing, never inferred. input: {path, limit?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-provenance\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.brief","description":"CONSTITUTION executive brief (spends AI budget, ONE high-tier synthesis — not a swarm): reasons over the whole DETERMINISTIC model (engineering health + axes, worst spots + broken laws, knowledge map, couplings, cross-analysis, deltas) → headline · state · 5-7 ranked moves. Grounded claim, parse-or-drop, on-demand. input: {snapshot_id?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-brief\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.constitution.classify","description":"CONSTITUTION ledger: mark a violation fixed|dismissed|known (one-click), or read the per-law tally with an advisory weight recommendation (always-dismissed law → suspend; always-fixed → raise-weight). The constitution learns; the operator still enacts. input: {op: classify|ledger, law_key?, path?, class?}.","owner_agent":"system","steps_json":"[{\"skill\":\"constitution-classify\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"}]"#).expect("ACTIONS: embedded JSON is valid by construction")
});

/// JS: `constitutionActions(_input, _context)` — returns the canonical data, verbatim.
pub fn constitutionActions(_input: &Value, _context: &Value) -> Value {
    ACTIONS.clone()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn actions_parses_with_the_pressed_shape() {
        let v: &Value = &ACTIONS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 24, "pressed length");
        let mut names: Vec<&str> = a.iter().map(|x| x["name"].as_str().expect("name")).collect();
        let n = names.len();
        names.sort(); names.dedup();
        assert_eq!(names.len(), n, "names unique");
    }

    #[test]
    fn constitutionactions_returns_the_static_verbatim() {
        assert_eq!(constitutionActions(&Value::Null, &Value::Null), *ACTIONS);
    }

}
